using UnityEngine; using UnityEditor; using Alpha.Data; [InitializeOnLoad] public class CreateExecutioner { static CreateExecutioner() { EditorApplication.delayCall += () => { var path = "Assets/scripts/Alpha/Data/Executioner_Series.asset"; if (AssetDatabase.LoadAssetAtPath<WeaponSeriesData_Alpha>(path) == null) { WeaponSeriesData_Alpha data = ScriptableObject.CreateInstance<WeaponSeriesData_Alpha>(); data.seriesName = "Executioner"; AssetDatabase.CreateAsset(data, path); AssetDatabase.SaveAssets(); Debug.Log("Created Executioner"); } }; } }
